def describe(name):
    if name in SPECS: return dict(SPECS[name])
    for prefix,title,explanation in [
        ('st_','Raw parse state','Inherited raw numeric state: 0=positive, 1=zero, 2=negative, 3=observation missing, 4=source absent, 5=parse failure.'),
        ('vs_','Source validity','Inherited source-interpretation state: 0=observed/verified, 1=observed zero, 2=negative, 3=missing, 4=source absent, 5=parse failure, 6=invalid code, 7=code evidence missing, 8=outside universe, 9=retired incompatible alias, 10=provisional observed.'),
        ('qs_','Quantity source state','Inherited quantity-test source status, copied from the corresponding vs_ field. Same 0-10 status meanings; not a quantity.'),
        ('qn_','Negative quantity?','1=negative, 0=nonnegative, missing=not assessable. Evaluated only for applicable years, source state 0/1/2 and nonmissing quantity.'),
        ('v_','Verified-only','Companion to the working standardized category, populated only where source interpretation was verified; provisional interpretations are excluded.')]:
        if name.startswith(prefix):
            base=describe(name[len(prefix):]); short=base['label'].split(';')[0]
            # Name uniquely identifies the target when the expanded concept would
            # exceed Stata's limit; full definition always expands it below.
            lab=f'{title}: {short}'
            if len(lab)>80: lab=f'{title}: {name[len(prefix):]}'
            return dict(name=name,label=lab,definition=f'{title} for {base["label"]}. {explanation} Kept from G0 through masking; it is not a newly computed diagnostic of the masked value.',unit='source category/code',source=base['source']+'; '+CORR)
    if name.endswith('_state') and name[:-6] in SPECS:
        base=describe(name[:-6]); return dict(name=name,label='Calculation status: '+name[:-6],definition='Inherited calculation-domain status for '+base['label']+'. Codes: 0=calculated, 1=zero input, 2=negative input, 3=missing input, 4=invalid worker denominator (ratio fields), 9=year/concept not admitted. Interpret in the corresponding per-worker/log correction edge; status retained through masking.',unit='calculation-state code',source=CORR)
    for n in ['gj_fuel_s1','elec_purchased_kwh','gj_electricity','co2_scope1_s1','co2_scope2_s1','total_gj_s1','co2_total_s1']:
        if name=='r_'+n:
            b=describe(n); return dict(name=name,label='Repaired '+b['label'][0].lower()+b['label'][1:],definition='Repaired subtotal on the inherited source availability mask. '+b['definition'],unit=b['unit'],source=CORR+'; downstream/obscure/strong/policy.py')
        if name=='r_'+n+'_n': return dict(name=name,label='Observed component count for repaired '+n,definition='Number of nonnegative, nonmissing components used by the repaired subtotal; preserves G0 component availability. Not a count of firms or years.',unit='component count',source=CORR)
    raise KeyError('No reviewed definition: '+name)
